CREATE OR REPLACE FUNCTION public.spell_bar_clear_school(p_world uuid, p_uid uuid, p_school text)
 RETURNS void
 LANGUAGE sql
AS $function$
  update player p set spell_bar = (
    select jsonb_agg(case when exists (select 1 from spell_any sa where sa.school = p_school and sa.id = p.spell_bar->>s.slot)
                          then 'null'::jsonb
